-- Seed: Indicadores de 6to de Secundaria - Lengua Española

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('6to', 'Lengua Española', 'BC1', 'IL-1', 'Identifica textos para comunicarse en variadas situaciones y en contextos diversos, para el fortalecimiento de las relaciones sociales mediante recursos tecnológicos, así como de otros tipos.'),
('6to', 'Lengua Española', 'BC1', 'IL-2', 'Utiliza textos funcionales y literarios en sus relaciones comunicativas, fortaleciendo sus conocimientos lingüísticos en el uso y a través de tecnologías y otros recursos.'),
('6to', 'Lengua Española', 'BC1', 'IL-3', 'Se comunica de manera efectiva mediante un tipo de texto, atendiendo a temas sociales del ámbito local, nacional y del mundo, de manera crítica y creativa.'),

-- BC2
('6to', 'Lengua Española', 'BC2', 'IL-4', 'Evidencia habilidades de producción y comprensión en el uso de secuencias argumentativas, para el abordaje de temas sociales diversos en ámbitos determinados.'),
('6to', 'Lengua Española', 'BC2', 'IL-5', 'Produce conocimientos innovadores a partir de la comprensión y producción de textos variados, explicando temáticas sociales de diferentes ámbitos.'),
('6to', 'Lengua Española', 'BC2', 'IL-6', 'Presenta informaciones analíticas de juicios y puntos de vista, en la construcción de un pensamiento estructurado, tomando en cuenta el respeto de las opiniones ajenas.'),
('6to', 'Lengua Española', 'BC2', 'IL-7', 'Hace uso de sus conocimientos sobre problemas sociales, a fin de encontrar soluciones posibles y explicarlas mediante el empleo de textos convenientes.'),
('6to', 'Lengua Española', 'BC2', 'IL-8', 'Usa tipologías textuales para tratar temas o problemas de la comunicad, con informaciones relevantes que ofrecen propuestas de solución.'),
('6to', 'Lengua Española', 'BC2', 'IL-9', 'Elabora textos variados que presentan conclusiones y recomendaciones producto de investigaciones que tratan sobre problemas de diferentes ámbitos sociales, aportando soluciones.'),

-- BC3
('6to', 'Lengua Española', 'BC3', 'IL-13', 'Desarrolla procesos investigativos con mayor nivel de profundidad sobre temas y problemas de la comunidad y fuera de esta, presentándolos a través de textos apropiados y haciendo uso de recursos tecnológicos, entre otros.'),
('6to', 'Lengua Española', 'BC3', 'IL-14', 'Emplea diversidad de textos priorizando los de secuencia expositivo-explicativa, en la puesta en conocimiento de los hallazgos, las conclusiones y recomendaciones de investigaciones sobre temas sociales variados.'),
('6to', 'Lengua Española', 'BC3', 'IL-15', 'Promueve y valora, mediante textos diversos, los procesos de investigación científica y tecnológica, sobre temas y problemas que inciden en la escuela, comunidad, a nivel nacional e internacional, como forma de conocer la realidad social y aportar soluciones.'),
('6to', 'Lengua Española', 'BC3', 'IL-16', 'Analiza con profundidad problemas y temas relacionados con salud, ambiente, alimentación, fauna, flora, a través de textos convenientes y el apoyo de herramientas que facilitan la tecnología de la información y la comunicación (TIC), entre otros medios y recursos, presentando conclusiones y recomendaciones de solución.'),
('6to', 'Lengua Española', 'BC3', 'IL-17', 'Utiliza textos como el catálogo, artículo de opinión, instructivo, la receta, para poner en conocimiento y buscar solución a problemas comunitarios sobre salud, ambiente, alimentación, ecosistema, entre otros.'),
('6to', 'Lengua Española', 'BC3', 'IL-18', 'Desarrolla actividades de intercomunicación en los que usa textos funcionales y literarios, para la concienciación de las personas a manifestar comportamientos positivos y realizar acciones en beneficio de la salud ciudadana, cuidado la naturaleza en general.'),

-- BC4
('6to', 'Lengua Española', 'BC4', 'IL-10', 'Utiliza textos apropiados para identificar nuevas relaciones socioculturales en las situaciones de comunicación de la comunidad que tiene incidencia participativa.'),
('6to', 'Lengua Española', 'BC4', 'IL-11', 'Fortalece la promoción de practices sociales de ciudadanía y los valores universales, en ámbitos variados y a través de la producción de textos convenientes.'),
('6to', 'Lengua Española', 'BC4', 'IL-12', 'Demuestra sus conocimientos sobre el uso de variedades textuales en la elaboración de proyectos sobre prácticas ciudadanas y explica sus conclusiones y recomendaciones como aportes a la solución de los problemas.'),
('6to', 'Lengua Española', 'BC4', 'IL-19', 'Usa variados tipos de textos para poner de relieve la comprensión de sí mismo, de manera más consciente, y sobre las demás personas con quienes convive, en procura de buenos comportamientos sociales.'),
('6to', 'Lengua Española', 'BC4', 'IL-20', 'Produce diversos textos funcionales y literarios sobre temas relacionados con valores universales y la dimensión humanista, a fin de fortalecer el buen comportamiento de sí mismo y de los demás que comparten su hábitat.'),
('6to', 'Lengua Española', 'BC4', 'IL-21', 'Valora y promueve informaciones de textos diversos (orales y escritos), relacionadas con temáticas de la sociedad referidas a las emociones, los sentimientos, valores espirituales, con miras a apoyar el respeto a la dignidad de las personas con las que nos relacionamos, en contextos local, nacional e internacional.');
